def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining_space = bins - item
    return np.where(remaining_space >= 0, -remaining_space, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    diff = np.abs(2 * item - bins)
    return np.where(bins >= item, -diff, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    fits = bins >= item
    ratios = np.where(fits, item / bins, 0)
    return np.where(fits, -ratios, -np.inf)
